{"query": "
-- Index 1: participants_events.participant_id
-- Fixes: Seq Scan on pe (WHERE participant_id <= 50) + SubPlan 3 correlated filter
CREATE INDEX IF NOT EXISTS idx_participants_events_participant_id
    ON participants_events (participant_id);
"}

{"query": "
-- Index 2: participants_events (participant_id, event_id)  
-- Fixes: SubPlan 3 – join pe2 ON participant_id, then fetch event_id (covering)
CREATE INDEX IF NOT EXISTS idx_participants_events_participant_event
    ON participants_events (participant_id, event_id);
"}

{"query": "
-- Index 4: events (id, start_date_time) 
-- Fixes: SubPlan 3 – allows index-only scan when fetching MAX(start_date_time) by event id
CREATE INDEX IF NOT EXISTS idx_events_id_start_date
    ON events (id, start_date_time);
"}
